<?php require '../includes/bootstrap.php';$user=staff_required();$title='Đơn đặt phòng';
$stats=query("SELECT COALESCE(SUM(status='pending'),0) pending,COALESCE(SUM(status='checked_in'),0) staying,COALESCE(SUM(status='confirmed' AND check_in=CURDATE()),0) arriving,COALESCE(SUM(status='checked_in' AND check_out<=CURDATE()),0) leaving FROM bookings")->fetch();
$filter=input('status');$search=input('q');$where='1=1';$args=[];
if(in_array($filter,['pending','confirmed','checked_in','completed','cancelled'],true)){$where.=' AND b.status=?';$args[]=$filter;}
if($search!==''){$where.=' AND (b.code LIKE ? OR b.guest_name LIKE ? OR b.email LIKE ?)';for($i=0;$i<3;$i++)$args[]='%'.$search.'%';}
$count=(int)query('SELECT COUNT(*) FROM bookings b WHERE '.$where,$args)->fetchColumn();$pages=max(1,(int)ceil($count/20));$page=max(1,min($pages,(int)input('page','1')));$offset=($page-1)*20;
$rows=query('SELECT b.*,r.name room_name FROM bookings b JOIN room_types r ON r.id=b.room_type_id WHERE '.$where.' ORDER BY b.id DESC LIMIT 20 OFFSET '.$offset,$args)->fetchAll();require '../includes/staff_header.php'; ?>
<div class="stats"><div><span>Chờ xác nhận</span><strong><?=$stats['pending']?></strong></div><div><span>Đến hôm nay</span><strong><?=$stats['arriving']?></strong></div><div><span>Đang lưu trú</span><strong><?=$stats['staying']?></strong></div><div><span>Cần trả phòng hôm nay / quá hạn</span><strong><?=$stats['leaving']?></strong></div></div><div class="actions align-left"><a class="button" href="<?=e(url('reception/new.php'))?>">+ TẠO ĐƠN TẠI QUẦY</a><a class="button outline" href="<?=e(url('reception/rooms.php'))?>">SƠ ĐỒ PHÒNG</a></div>
<form method="get" class="filter"><label>Tìm đơn<input name="q" value="<?=e($search)?>" placeholder="Mã đơn, tên hoặc email"></label><label>Trạng thái<select name="status"><option value="">Tất cả</option><?php foreach(['pending','confirmed','checked_in','completed','cancelled'] as $s): ?><option value="<?=$s?>" <?=$filter===$s?'selected':''?>><?=e(status_name($s))?></option><?php endforeach; ?></select></label><button class="button">LỌC ĐƠN</button></form><p><?=$count?> đơn · Trang <?=$page?>/<?=$pages?></p>
<div class="table-wrap"><table><thead><tr><th>Khách hàng</th><th>Phòng / lưu trú</th><th>Tổng tiền</th><th>Trạng thái</th><th></th></tr></thead><tbody><?php foreach($rows as $b): ?><tr><td><strong><?=e($b['guest_name'])?></strong><br><?=e($b['phone'])?><br><small>#<?=$b['id']?> · <?=$b['source']==='online'?'Trực tuyến':'Tại quầy'?></small></td><td><?=e($b['room_name'])?><br><?=e($b['check_in'])?> → <?=e($b['check_out'])?><br><?=$b['quantity']?> phòng · <?=$b['guests']?> khách</td><td><?=money($b['total_price'])?></td><td><span class="badge"><?=e(status_name($b['status']))?></span></td><td><a class="text-link" href="<?=e(url('reception/booking.php?id='.$b['id']))?>">Xử lý đơn ↗</a></td></tr><?php endforeach; if(!$rows): ?><tr><td colspan="5">Chưa có đơn phù hợp.</td></tr><?php endif; ?></tbody></table></div><div class="actions"><?php if($page>1): ?><a class="button outline" href="?<?=e(http_build_query(['q'=>$search,'status'=>$filter,'page'=>$page-1]))?>">← TRƯỚC</a><?php endif; if($page<$pages): ?><a class="button outline" href="?<?=e(http_build_query(['q'=>$search,'status'=>$filter,'page'=>$page+1]))?>">TIẾP →</a><?php endif; ?></div><?php require '../includes/staff_footer.php'; ?>
